import React from 'react';
import { NavLink } from 'react-router-dom';
import {
  FiHome,
  FiCalendar,
  FiImage,
  FiVideo,
  FiBriefcase,
  FiBook,
  FiMessageSquare,
  FiSettings,
  FiStar,
} from 'react-icons/fi';

const AdminSidebar = () => {
  const menuItems = [
    { path: '/', label: 'Dashboard', icon: FiHome },
    { path: '/events', label: 'Events', icon: FiCalendar },
    { path: '/gallery', label: 'Gallery', icon: FiImage },
    { path: '/videos', label: 'Videos', icon: FiVideo },
    { path: '/services', label: 'Services', icon: FiBriefcase },
    { path: '/courses', label: 'Courses', icon: FiBook },
    { path: '/messages', label: 'Messages', icon: FiMessageSquare },
    { path: '/testimonials', label: 'Testimonials', icon: FiStar },
    { path: '/settings', label: 'Settings', icon: FiSettings },
  ];

  return (
    <aside className="fixed left-0 top-16 bottom-0 w-64 bg-blue-900 text-white shadow-xl overflow-y-auto z-40">
      <div className="p-4 pt-5">
        <div className="space-y-1">
          {menuItems.map((item) => (
            <NavLink
              key={item.path}
              to={item.path}
              end={item.path === '/'}
              className={({ isActive }) =>
                `flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 ${
                  isActive
                    ? 'bg-yellow-400 text-blue-900 font-bold shadow-md'
                    : 'text-blue-200 hover:bg-blue-800/60 hover:text-white'
                }`
              }
            >
              <item.icon className={`text-lg ${item.path === '/' ? '' : ''}`} />
              <span className="text-sm font-medium">{item.label}</span>
              {item.label === 'Messages' && (
                <span className="ml-auto w-5 h-5 bg-red-500 rounded-full flex items-center justify-center text-[10px] font-bold text-white">
                  3
                </span>
              )}
            </NavLink>
          ))}
        </div>

        <div className="mt-8 pt-6 border-t border-blue-800/50">
          <div className="px-4 py-3 bg-blue-800/40 rounded-xl">
            <p className="text-xs text-blue-300 font-medium uppercase tracking-wider">System</p>
            <p className="text-[11px] text-blue-400 mt-1">Version 1.0.0</p>
          </div>
        </div>
      </div>
    </aside>
  );
};

export default AdminSidebar;
